insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa succede alla prima valutazione?', $qoer736$["come funziona la prima valutazione","cosa si fa alla prima visita","cosa succede alla prima visita","in cosa consiste la prima valutazione","come funziona la prima visita","cosa si fa nella prima visita","cosa succede alla prima valutazione"]$qoer736$::jsonb, 'In genere la prima valutazione comprende alcune domande sul problema e sulla sua storia, l''osservazione dei movimenti e dei test specifici sulla zona interessata. Al termine il fisioterapista le illustra il percorso che ritiene più adatto. I dettagli possono variare da studio a studio.', $qgzkj6r${}$qgzkj6r$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quante sedute servono?', $qvdcgt0$["quante sedute servono","quante sedute mi servono","quante sedute devo fare","di quante sedute ho bisogno","quante sedute ci vogliono","quante sedute sono necessarie"]$qvdcgt0$::jsonb, 'Il numero di sedute dipende dalla valutazione: varia in base al problema, a da quanto tempo c''è e alla persona, quindi non si può stabilire prima di averla valutata. È il fisioterapista a indicarlo dopo la prima valutazione.', $qsbmyx4${}$qsbmyx4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quanto dura una seduta?', $q8k3w04$["quanto dura una seduta","quanto dura la seduta","quanto tempo dura la seduta","una seduta quanto dura","quanto tempo ci vuole per una seduta"]$q8k3w04$::jsonb, 'La durata della seduta dipende dal tipo di trattamento e da come è organizzato lo studio: per il tempo esatto è meglio verificare direttamente con lo studio.', $q0if7x6${}$q0if7x6$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Ogni quanto si fanno le sedute?', $qhkd3lh$["ogni quanto si fanno le sedute","quante volte a settimana","quante sedute a settimana","con che frequenza si fanno le sedute","ogni quanto devo venire","ogni quanto vanno fatte le sedute"]$qhkd3lh$::jsonb, 'La frequenza delle sedute viene stabilita dal fisioterapista dopo la valutazione, in base al problema e al tipo di trattamento.', $qoptefl${}$qoptefl$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quanto dura il percorso di fisioterapia?', $qkz4ifx$["quanto dura il percorso di fisioterapia","quanto dura il ciclo di sedute","quanto dura il ciclo","quanto dura la terapia","quanto dura la riabilitazione","quanto tempo serve per recuperare","quanto dura la riabilitazione dopo l intervento"]$qkz4ifx$::jsonb, 'La durata del percorso varia molto da persona a persona e dipende dal problema e dalla situazione di partenza: viene definita dal fisioterapista dopo la valutazione, non è possibile indicarla in anticipo.', $qs3sxdo${}$qs3sxdo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è un ciclo di sedute?', $qc7cf08$["cos e un ciclo di sedute","cosa significa ciclo di sedute","in cosa consiste il ciclo di sedute","cosa vuol dire ciclo di sedute","come funziona il ciclo di sedute"]$qc7cf08$::jsonb, 'Un ciclo è un percorso composto da più sedute, definito dal fisioterapista dopo la valutazione. Numero e cadenza delle sedute dipendono dal singolo caso.', $qaz2b91${}$qaz2b91$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Serve l''impegnativa o la prescrizione medica?', $q8x2fce$["serve l impegnativa","serve la prescrizione","serve la prescrizione medica","serve la ricetta del medico","ci vuole l impegnativa","serve l impegnativa del medico","posso venire senza impegnativa","posso venire senza prescrizione","si puo venire senza impegnativa","serve la richiesta del medico","ci vuole la prescrizione","serve il certificato medico"]$q8x2fce$::jsonb, 'Dipende dallo studio e dal tipo di percorso (per esempio privato oppure in convenzione): in alcuni casi la prescrizione medica è richiesta, in altri no. È un aspetto da verificare con lo studio al momento della prenotazione.', $qsdjkd2${}$qsdjkd2$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Cosa devo portare alla prima valutazione?', $qbq5yf5$["cosa devo portare alla prima visita","cosa devo portare alla visita","cosa devo portare alla prima valutazione","che documenti servono per la prima visita","devo portare qualcosa alla prima visita","cosa serve portare","cosa devo portare","che documenti servono"]$qbq5yf5$::jsonb, 'Alla prima valutazione è utile portare un documento di identità, la tessera sanitaria, gli eventuali referti ed esami già fatti (per esempio risonanza, radiografie, ecografie), la prescrizione se ne ha una e l''indicazione di eventuali interventi o terapie in corso. Per indicazioni precise verifichi con lo studio.', $qyn9cn1${}$qyn9cn1$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_documenti', 'Devo portare la risonanza o gli esami?', $qrl3e3y$["devo portare la risonanza","devo portare le radiografie","devo portare gli esami","devo portare i referti","servono gli esami","serve la risonanza","serve la risonanza prima della visita","serve il referto","devo fare la risonanza prima"]$qrl3e3y$::jsonb, 'Se ha già referti o esami (per esempio risonanza, radiografie, ecografie) è utile portarli: il fisioterapista li valuta insieme alla visita. Non sempre servono esami prima di venire: se ne serviranno, sarà il professionista a dirlo.', $qliu9xv${}$qliu9xv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Come mi devo vestire per la seduta?', $qcjpywa$["come mi devo vestire","cosa devo mettere","abbigliamento per la seduta","posso venire in jeans","cosa indossare alla visita","come mi vesto per la visita"]$qcjpywa$::jsonb, 'È consigliabile un abbigliamento comodo, che permetta di muoversi e di scoprire facilmente la zona da valutare (per esempio una maglietta comoda e pantaloncini).', $q4kmd08${}$q4kmd08$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Che differenza c''è tra fisioterapista, fisiatra e osteopata?', $qcp3xli$["che differenza c e tra fisioterapista e osteopata","differenza tra fisioterapista e fisiatra","differenza fisioterapista osteopata","chi e il fisiatra","fisioterapista o osteopata","fisioterapista o fisiatra"]$qcp3xli$::jsonb, 'Il fisiatra è un medico specializzato in riabilitazione; il fisioterapista è il professionista sanitario che valuta il movimento e svolge i trattamenti riabilitativi; l''osteopata ha un approccio manuale con un proprio percorso formativo. Per capire a chi rivolgersi nel suo caso, la prima valutazione è il punto di partenza.', $qyzuw9s${}$qyzuw9s$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la tecarterapia?', $q2af9tk$["cos e la tecarterapia","come funziona la tecarterapia","cosa e la tecar","cos e la tecar","tecar cos e","cosa significa tecarterapia"]$q2af9tk$::jsonb, 'La tecarterapia è una terapia strumentale che utilizza energia a radiofrequenza applicata sulla zona da trattare. Se sia indicata nel suo caso lo decide il professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $q1azuo6${}$q1azuo6$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la laserterapia?', $qe8r57c$["cos e la laserterapia","come funziona la laserterapia","cos e il laser","come funziona il laser","cosa e la terapia laser"]$qe8r57c$::jsonb, 'La laserterapia è una terapia strumentale che utilizza una luce laser applicata sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $qfmehhc${}$qfmehhc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa sono le onde d''urto?', $qey2jsd$["cosa sono le onde d urto","come funzionano le onde d urto","cos e la terapia con onde d urto","in cosa consistono le onde d urto","cosa sono le onde urto"]$qey2jsd$::jsonb, 'Le onde d''urto sono una terapia strumentale che usa onde acustiche applicate sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio la utilizza chieda direttamente allo studio.', $qlya0ow${}$qlya0ow$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cosa sono gli ultrasuoni?', $qccfbr7$["cosa sono gli ultrasuoni","come funzionano gli ultrasuoni","cos e l ultrasuonoterapia","cos e la terapia a ultrasuoni"]$qccfbr7$::jsonb, 'Gli ultrasuoni sono una terapia strumentale che utilizza onde sonore ad alta frequenza applicate sulla zona da trattare. L''indicazione spetta al professionista; per sapere se lo studio li utilizza chieda direttamente allo studio.', $q3eduux${}$q3eduux$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la massoterapia?', $qzhevkk$["cos e la massoterapia","cosa e la massoterapia","in cosa consiste la massoterapia","cos e il massaggio terapeutico","differenza tra massaggio e massoterapia"]$qzhevkk$::jsonb, 'La massoterapia è un trattamento manuale con tecniche di massaggio a scopo terapeutico, svolto da personale qualificato. Se sia indicata nel suo caso lo valuta il professionista; per sapere se lo studio la offre chieda direttamente allo studio.', $qdnfzgm${}$qdnfzgm$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è l''osteopatia?', $qc3jv7t$["cos e l osteopatia","cosa e l osteopatia","in cosa consiste l osteopatia","come funziona l osteopatia","cosa fa l osteopata"]$qc3jv7t$::jsonb, 'L''osteopatia è un approccio manuale che valuta e tratta il corpo nel suo insieme. Per sapere se lo studio offre questo servizio e con quale professionista, chieda direttamente allo studio.', $qf63d42${}$qf63d42$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la rieducazione posturale?', $qq53547$["cos e la rieducazione posturale","cosa e la rieducazione posturale","in cosa consiste la rieducazione posturale","come funziona la rieducazione posturale","cos e la ginnastica posturale"]$qq53547$::jsonb, 'La rieducazione posturale è un percorso di esercizi e di lavoro sulla postura guidato dal fisioterapista, impostato dopo una valutazione. Per sapere se lo studio la offre chieda direttamente allo studio.', $qia4wog${}$qia4wog$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la terapia manuale o la mobilizzazione?', $q033u6r$["cos e la terapia manuale","cos e la mobilizzazione","cosa significa mobilizzazione","in cosa consiste la terapia manuale","cosa sono le mobilizzazioni"]$q033u6r$::jsonb, 'La terapia manuale comprende tecniche eseguite con le mani dal fisioterapista, come la mobilizzazione delle articolazioni e dei tessuti, scelte dopo la valutazione.', $qu42q39${}$qu42q39$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Cos''è la ginnastica riabilitativa?', $qujhz6j$["cos e la ginnastica riabilitativa","cosa e la ginnastica riabilitativa","in cosa consiste la ginnastica riabilitativa","cos e la riabilitazione attiva"]$qujhz6j$::jsonb, 'La ginnastica riabilitativa è un percorso di esercizi impostato dal fisioterapista sulla base della valutazione e seguito in seduta. Gli esercizi adatti a lei li stabilisce il professionista, non possono essere indicati in chat.', $q0c2yvd${}$q0c2yvd$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'La seduta fa male?', $qw0qefe$["fa male la seduta","fa male la fisioterapia","la seduta e dolorosa","il trattamento e doloroso","la tecarterapia fa male","fa male il massaggio","fa male il trattamento"]$qw0qefe$::jsonb, 'Dipende dal tipo di trattamento e dalla persona. Il fisioterapista adatta l''intensità e va avvisato di qualsiasi fastidio durante la seduta.', $qclyx4h${}$qclyx4h$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Quando si può iniziare la riabilitazione dopo un intervento?', $qc26vnn$["quando iniziare la riabilitazione","quando si inizia la fisioterapia dopo l intervento","dopo quanto tempo dall intervento posso iniziare","quando posso iniziare dopo l operazione","quando posso cominciare la riabilitazione","quando devo iniziare la fisioterapia dopo l operazione"]$qc26vnn$::jsonb, 'Il momento giusto dipende dal tipo di intervento e dalle indicazioni del chirurgo: è importante seguire quanto le ha detto. Può comunque contattare lo studio per organizzare la valutazione.', $qki8tfq${}$qki8tfq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Serve una diagnosi prima di venire?', $q21cirt$["serve una diagnosi prima di venire","devo avere una diagnosi per venire","devo avere la diagnosi del medico","senza diagnosi posso venire","posso venire senza sapere cos ho"]$q21cirt$::jsonb, 'Non sempre serve avere già una diagnosi: la prima valutazione serve proprio a capire la situazione. Se ha già referti o indicazioni del medico, è utile portarli.', $qjfcl2q${}$qjfcl2q$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Posso fare fisioterapia in gravidanza?', $q6gzxwv$["sono incinta posso fare fisioterapia","in gravidanza posso venire","sono in gravidanza posso fare la seduta","fisioterapia in gravidanza","sono incinta posso venire"]$q6gzxwv$::jsonb, 'Se è in gravidanza lo comunichi allo studio al momento della prenotazione: il fisioterapista valuta cosa è adatto al suo caso.', $qotjdiy${}$qotjdiy$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('fisioterapista', 1, 'production', 'info_trattamenti', 'Posso prenotare per un familiare?', $qpw7k2g$["posso prenotare per mio padre","posso prenotare per mia madre","posso prenotare per un familiare","prenotare per un altra persona","prenoto per mio marito"]$qpw7k2g$::jsonb, 'In genere sì: basta indicare il nome della persona che verrà vista. Per eventuali indicazioni particolari, per esempio per minori, chieda allo studio.', $qkol2i3${}$qkol2i3$::jsonb);
insert into sector_eval_runs (profile_id, settore, version, scenari_totali, scenari_passati, metriche, gate_passed, note)
